<section class="content"><h1>Mis direcciones</h1><?php if($addresses):?><table class="table"><tr><th>Alias</th><th>Dirección</th><th>Localidad</th></tr><?php foreach($addresses as $a):?><tr><td><?=h($a['alias'])?></td><td><?=h($a['calle'].' '.$a['numero'].' '.$a['piso_departamento'])?></td><td><?=h($a['ciudad'].', '.$a['provincia'].' · '.$a['codigo_postal'])?></td></tr><?php endforeach?></table><?php else:?><div class="empty">Todavía no guardaste direcciones.</div><?php endif?><form class="form" method="post" action="?action=address_add"><?=csrf_field()?><h2>Agregar dirección</h2><label>Alias</label><input name="alias" value="Casa"><label>Calle</label><input name="calle" required><label>Número</label><input name="numero" required><label>Piso/departamento</label><input name="piso_departamento"><label>Ciudad</label><input name="ciudad" required><label>Provincia</label><input name="provincia" required><label>Código postal</label><input name="codigo_postal" required><label>Referencia</label><input name="referencia"><button class="btn">Guardar dirección</button></form></section>
